    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_111'), 'The fix that shipped. The root layout no longer imports next/headers:

// app/layout.tsx
export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: THEME_SCRIPT }} />
      </head>
      <body>{children}</body>
    </html>
  );
}
// THEME_SCRIPT reads the theme cookie in the browser and sets data-theme on <html> before the first paint.

$ curl -sI https://app.codedev.test/courses | grep -i x-nextjs-cache
x-nextjs-cache: HIT

Statement: "Now that the catalog HTML comes from a shared cache, the server sends the same HTML to every visitor, so the theme has to be applied in the browser instead of being chosen by the server."', 'single_choice'::question_type, 'True. x-nextjs-cache: HIT means this response was served from the Next.js cache, which is one copy of the HTML for everyone; nothing in it can depend on who asked. A per-visitor detail like the theme therefore moves to the browser: the inline script reads the cookie and sets data-theme before the page is painted, which avoids a flash of the wrong theme. suppressHydrationWarning on <html> is needed because the script changes that attribute before React hydrates. The misconception is that you can keep a cached page and still personalise its HTML on the server; you can personalise it in the browser, or render that part per request, but not both cache and vary the same HTML.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_111') AND order_index = 2)
    RETURNING id
)
