INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nrc_112', (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nrc-1-1' AND is_deleted = false LIMIT 1), 'choose-rendering-strategy', 'Choose a rendering strategy for every route', 'After the catalog incident (GET /courses was rendered on every request because the root layout read cookies() for the theme, and TTFB tripled under load), the CodeDev team runs the traits of every route through one function before each release. Write chooseRendering(page), which returns { route, strategy, reason } for a page { route, freshnessSeconds, perUserData, reads, pageCount, dataAtBuild, seo }. freshnessSeconds is how old the HTML may be (null = it changes only with a deploy, 0 = it must be fresh on every request); reads lists the request-time APIs read by the page or any layout above it; pageCount is how many pages the route produces; dataAtBuild says whether the data source can be reached during next build. Apply the rules in this order: (1) invalid traits give strategy "invalid" and reason "invalid traits": freshnessSeconds that is not null and not a whole number >= 0, pageCount that is not a whole number >= 1, or reads that is not an array or contains anything other than "cookies", "headers", "searchParams". (2) perUserData true: "dynamic", reason "per-user data". (3) reads not empty: "dynamic", reason "reads " followed by the distinct names it contains in the fixed order cookies, headers, searchParams, joined with ", " (for example "reads cookies, searchParams"). (4) freshnessSeconds 0: "dynamic", reason "must be fresh on every request". (5) The HTML is "prerendered at build" when dataAtBuild is true and pageCount is at most 1000, otherwise it is "rendered on first request". (6) freshnessSeconds null: "static", reason = the text from rule 5. (7) freshnessSeconds above 0: strategy "isr:<seconds>" (for example "isr:300"), reason = the text from rule 5 + ", revalidated every <seconds> s". seo never changes the strategy: static, ISR and dynamic pages all send complete HTML to crawlers. The test runner reads a list of pages as JSON and prints one decision per page.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
