"use client";
import { useState } from "react";
import { Syllabus } from "./Syllabus";
import { Reviews } from "./Reviews";
import { ProgressChart } from "@/components/ProgressChart";   // uses a chart library

export function CourseBody({ course }: { course: Course }) {
  const [showAll, setShowAll] = useState(false);
  return (
    <>
      <Syllabus modules={course.modules} showAll={showAll} />
      <button onClick={() => setShowAll(!showAll)}>Show all lessons</button>
      <ProgressChart points={course.stats} />
      <Reviews reviews={course.reviews} />
    </>
  );
}

// app/courses/[slug]/Reviews.tsx   (the file has no directive)
export function Reviews({ reviews }: { reviews: Review[] }) {
  return <ul>{reviews.map((r) => <li key={r.id}>{r.text}</li>)}</ul>;
}

Statement: "Reviews.tsx has no \"use client\" line, so it is still a server component and its code is not sent to the browser."', 'single_choice'::question_type, 'False. "use client" marks a boundary in the module graph: the file that has it and every module it imports become client code. CourseBody imports Reviews, so Reviews is bundled for the browser even though its own file has no directive (the same happens to Syllabus and to ProgressChart with its chart library). A component without a directive is a server component only when it is imported from server code. The misconception is that the directive is a per-file label; it is an entry point, and everything behind it follows. The fix is to keep CourseBody small (only the toggle) and let the server page render Reviews, passing it in as children if it must appear inside a client component.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_121') AND order_index = 1)
    RETURNING id
)
