-- challenge chal_coding_nrc_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nrc_122', (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nrc-1-2' AND is_deleted = false LIMIT 1), 'plan-client-boundaries', 'Push "use client" down to the leaves', 'On the CodeDev course page someone put "use client" at the top of the page, and the chart library and the whole page became client code. Write planBoundaries(root) for a component tree whose nodes are { name, uses?, ownKb?, libKb?, props?, children? }: uses lists features from "state", "effect", "eventHandler", "browserApi", "secret", "database"; ownKb is the component''s own gzipped size and libKb a heavy library it imports; props maps each prop its parent passes to a kind; children are the components it imports and renders. Walk the tree depth-first (a parent before its children, children in the given order) and return { components, useClient, badProps, conflicts, clientKb }. components: one { name, runsOn } per component; runsOn is "client" when the component uses state, effect, eventHandler or browserApi, or when its parent runs on the client (everything a client component imports is client code), otherwise "server". useClient: the components whose file needs "use client": client components whose parent runs on the server, and the root if it runs on the client; nothing below a boundary gets it. badProps: for each "use client" component except the root, every prop its server parent passes that cannot cross the boundary, as "<Component>.<prop> (<kind>)" in prop order. Kinds that can cross: "string", "number", "boolean", "null", "array", "plainObject", "date" (React 19 serializes Date), "jsx" and "serverAction"; "function", "classInstance" and any other kind cannot. Props between two client components are never reported. conflicts: client components that use "secret" or "database". clientKb: the sum of ownKb + libKb over all client components, rounded to 1 decimal. Invalid input: a missing uses, props or children means empty; an ownKb or libKb that is missing or not a finite number >= 0 counts as 0; unknown features are ignored. The test runner reads the root as JSON and prints the plan.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
