INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_122'), 1, 'What does a component need to know about its parent to decide where it runs, whether it needs its own "use client" line and whether its props cross the network?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_122'), 2, 'A recursive visit(node, parentRunsOn) that receives the parent''s decision is enough: the root has no parent (neither server nor client), a client parent forces client, and only the step from a server parent to a client child is a boundary. Check props and add the directive at that step only. Sum the sizes as you go and round once at the end.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_122'), 3, 'A similar tree that is not in the tests: QuizPage (database) renders Timer (effect, props { endsAt: date, onEnd: function }) and Question (no features); Timer renders Clock (no features, props { onTick: function }). Timer is a boundary under a server parent: it gets "use client", endsAt crosses, onEnd is reported as "Timer.onEnd (function)". Clock runs on the client because Timer imports it, needs no directive, and its onTick is not checked. Question stays on the server and adds nothing to the client size.');
