"use client";
export function ContinueLink() {
  const last = typeof window !== "undefined" ? localStorage.getItem("lastLesson") : null;
  return (
    <a href={last ?? "/courses"}>
      {last ? "Continue where you left off" : "Browse courses"}
    </a>
  );
}

Statement: "Because the file starts with \"use client\", this component runs only in the browser, so the typeof window branch cannot cause a hydration mismatch."', 'single_choice'::question_type, 'False. A client component is rendered twice: on the server for the first HTML, where window is undefined and last is null ("Browse courses"), and in the browser during hydration, where a learner with a saved lesson gets "Continue where you left off". The two renders disagree, which is exactly a hydration mismatch. "use client" means the code also runs in the browser, not only there. Fix it by rendering the server version first and reading localStorage in an effect after hydration (or with useSyncExternalStore and a server snapshot), or by loading the component on the client only. The misconception is that typeof window protects a render; it guarantees the two renders differ.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_131') AND order_index = 3)
    RETURNING id
)
