-- challenge chal_coding_nrc_222 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nrc_222', (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nrc-2-2' AND is_deleted = false LIMIT 1), 'stale-page-or-data-leak', 'Stale Page or Data Leak?', 'Since Monday''s release, learners on app.codedev.test open their dashboard and sometimes see another learner''s name, lessons and streak; an anonymous visitor has seen a learner''s dashboard too. After a minute or so it fixes itself. The release cached the expensive dashboard query on the server (getDashboard) and added a Cache-Control header to the /api/dashboard route handler so the CDN could absorb the morning peak. Purging and bypassing the CDN did not stop the leak.

Fix the data layer and the route handler so that every learner only ever gets their own dashboard, with the CDN in front and with it bypassed, while: the dashboard query stays cached on the server for 60 seconds, one entry per learner (a second request by the same learner within 60 seconds must not query the database); /api/dashboard is sent with Cache-Control "private, no-cache"; anonymous requests still get 401 with "private, no-store"; and the course list stays public, cached on the server and by the CDN with "public, max-age=0, s-maxage=300".

The file contains a fake clock in seconds, the database (it counts queries), the server data cache cached(key, ttlSeconds, load), and a CDN that keys entries by path and query only (the session cookie is not part of its key) and stores 200 responses for s-maxage seconds unless Cache-Control contains private or no-store. Do not change them or the test runner.

Input: { "bypassCdn"?: boolean, "requests": [{ "at": seconds, "user": "u_lan" | null, "path": "/api/..." }, ...] }. The runner prints, per request, the status, the body, the CDN result (HIT, MISS or BYPASS) and the Cache-Control header, then the number of database queries.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222'), 1, 'There are two caches between a learner and the database. For each one, ask: what does it use as the key, and does that key contain everything that changes the dashboard? Then run the starter with the CDN bypassed: does the leak stop?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222'), 2, 'Look at the key passed to cached(...) in getDashboard and at the Cache-Control header the /api/dashboard branch of handle() returns. Compare both with what the course list does, and decide which parts of the course list''s caching are right for per-user data and which are not.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222'), 3, 'A similar case on a different route: a notifications endpoint cached as cached("notifications", 30, () => db.notificationsFor(userId)) with "public, s-maxage=30". Keying it as `notifications:${userId}` keeps one server entry per user, and sending "private, no-cache" stops shared caches from storing it; the public announcements endpoint next to it keeps its shared key and its public header.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222'), 'Lan, then Minh five seconds later: each sees their own dashboard', '{"requests":[{"at":0,"user":"u_lan","path":"/api/dashboard"},{"at":5,"user":"u_minh","path":"/api/dashboard"}]}', '"t=0 u_lan GET /api/dashboard -> 200 {\"name\":\"Lan\",\"lessonsDone\":3,\"streak\":2} | cdn MISS | private, no-cache\nt=5 u_minh GET /api/dashboard -> 200 {\"name\":\"Minh\",\"lessonsDone\":41,\"streak\":19} | cdn MISS | private, no-cache\ndb queries: dashboard=2 courses=0"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222'), 'The course list stays shared: three visitors, one database query, CDN hits', '{"requests":[{"at":0,"user":"u_lan","path":"/api/courses?category=react"},{"at":10,"user":"u_minh","path":"/api/courses?category=react"},{"at":20,"user":null,"path":"/api/courses?category=react"},{"at":25,"user":"u_lan","path":"/api/dashboard"}]}', '"t=0 u_lan GET /api/courses?category=react -> 200 [\"React Basics\",\"Hooks in Depth\"] | cdn MISS | public, max-age=0, s-maxage=300\nt=10 u_minh GET /api/courses?category=react -> 200 [\"React Basics\",\"Hooks in Depth\"] | cdn HIT | public, max-age=0, s-maxage=300\nt=20 anonymous GET /api/courses?category=react -> 200 [\"React Basics\",\"Hooks in Depth\"] | cdn HIT | public, max-age=0, s-maxage=300\nt=25 u_lan GET /api/dashboard -> 200 {\"name\":\"Lan\",\"lessonsDone\":3,\"streak\":2} | cdn MISS | private, no-cache\ndb queries: dashboard=1 courses=1"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222'), 'CDN bypassed (x-cache: BYPASS): the server cache must not mix learners either', '{"bypassCdn":true,"requests":[{"at":0,"user":"u_minh","path":"/api/dashboard"},{"at":12,"user":"u_lan","path":"/api/dashboard"},{"at":30,"user":"u_an","path":"/api/dashboard"},{"at":31,"user":"u_lan","path":"/api/courses?category=sql"}]}', '"t=0 u_minh GET /api/dashboard -> 200 {\"name\":\"Minh\",\"lessonsDone\":41,\"streak\":19} | cdn BYPASS | private, no-cache\nt=12 u_lan GET /api/dashboard -> 200 {\"name\":\"Lan\",\"lessonsDone\":3,\"streak\":2} | cdn BYPASS | private, no-cache\nt=30 u_an GET /api/dashboard -> 200 {\"name\":\"An\",\"lessonsDone\":12,\"streak\":5} | cdn BYPASS | private, no-cache\nt=31 u_lan GET /api/courses?category=sql -> 200 [\"SQL Basics\",\"Joins in Practice\"] | cdn BYPASS | public, max-age=0, s-maxage=300\ndb queries: dashboard=3 courses=1"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222'), 'An anonymous visitor after a learner gets 401, never a stored dashboard', '{"requests":[{"at":0,"user":"u_thu","path":"/api/dashboard"},{"at":3,"user":null,"path":"/api/dashboard"},{"at":4,"user":"u_thu","path":"/api/dashboard"}]}', '"t=0 u_thu GET /api/dashboard -> 200 {\"name\":\"Thu\",\"lessonsDone\":7,\"streak\":1} | cdn MISS | private, no-cache\nt=3 anonymous GET /api/dashboard -> 401 {\"error\":\"sign in\"} | cdn MISS | private, no-store\nt=4 u_thu GET /api/dashboard -> 200 {\"name\":\"Thu\",\"lessonsDone\":7,\"streak\":1} | cdn MISS | private, no-cache\ndb queries: dashboard=1 courses=0"', 2, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222'), 'Each learner''s dashboard stays cached on the server for 60 s, then is loaded again', '{"requests":[{"at":0,"user":"u_lan","path":"/api/dashboard"},{"at":30,"user":"u_lan","path":"/api/dashboard"},{"at":30,"user":"u_minh","path":"/api/dashboard"},{"at":59,"user":"u_lan","path":"/api/dashboard"},{"at":60,"user":"u_lan","path":"/api/dashboard"},{"at":89,"user":"u_minh","path":"/api/dashboard"},{"at":90,"user":"u_minh","path":"/api/dashboard"}]}', '"t=0 u_lan GET /api/dashboard -> 200 {\"name\":\"Lan\",\"lessonsDone\":3,\"streak\":2} | cdn MISS | private, no-cache\nt=30 u_lan GET /api/dashboard -> 200 {\"name\":\"Lan\",\"lessonsDone\":3,\"streak\":2} | cdn MISS | private, no-cache\nt=30 u_minh GET /api/dashboard -> 200 {\"name\":\"Minh\",\"lessonsDone\":41,\"streak\":19} | cdn MISS | private, no-cache\nt=59 u_lan GET /api/dashboard -> 200 {\"name\":\"Lan\",\"lessonsDone\":3,\"streak\":2} | cdn MISS | private, no-cache\nt=60 u_lan GET /api/dashboard -> 200 {\"name\":\"Lan\",\"lessonsDone\":3,\"streak\":2} | cdn MISS | private, no-cache\nt=89 u_minh GET /api/dashboard -> 200 {\"name\":\"Minh\",\"lessonsDone\":41,\"streak\":19} | cdn MISS | private, no-cache\nt=90 u_minh GET /api/dashboard -> 200 {\"name\":\"Minh\",\"lessonsDone\":41,\"streak\":19} | cdn MISS | private, no-cache\ndb queries: dashboard=4 courses=0"', 2, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222'), 'Query strings, a new learner, an unknown route and the course list after 300 s', '{"requests":[{"at":0,"user":"u_lan","path":"/api/dashboard?tab=streaks"},{"at":2,"user":"u_9001","path":"/api/dashboard?tab=streaks"},{"at":4,"user":"u_minh","path":"/api/leaderboard"},{"at":5,"user":null,"path":"/api/courses"},{"at":6,"user":"u_an","path":"/api/courses?category=%20SQL"},{"at":304,"user":"u_an","path":"/api/courses"},{"at":305,"user":"u_lan","path":"/api/courses"}]}', '"t=0 u_lan GET /api/dashboard?tab=streaks -> 200 {\"name\":\"Lan\",\"lessonsDone\":3,\"streak\":2} | cdn MISS | private, no-cache\nt=2 u_9001 GET /api/dashboard?tab=streaks -> 200 {\"name\":\"u_9001\",\"lessonsDone\":0,\"streak\":0} | cdn MISS | private, no-cache\nt=4 u_minh GET /api/leaderboard -> 404 {\"error\":\"not found\"} | cdn MISS | private, no-store\nt=5 anonymous GET /api/courses -> 200 [\"React Basics\",\"Hooks in Depth\",\"SQL Basics\",\"Joins in Practice\",\"Node Streams\"] | cdn MISS | public, max-age=0, s-maxage=300\nt=6 u_an GET /api/courses?category=%20SQL -> 200 [\"SQL Basics\",\"Joins in Practice\"] | cdn MISS | public, max-age=0, s-maxage=300\nt=304 u_an GET /api/courses -> 200 [\"React Basics\",\"Hooks in Depth\",\"SQL Basics\",\"Joins in Practice\",\"Node Streams\"] | cdn HIT | public, max-age=0, s-maxage=300\nt=305 u_lan GET /api/courses -> 200 [\"React Basics\",\"Hooks in Depth\",\"SQL Basics\",\"Joins in Practice\",\"Node Streams\"] | cdn MISS | public, max-age=0, s-maxage=300\ndb queries: dashboard=2 courses=3"', 2, false, true, 6),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_222'), 'Large: 280 requests over about ten minutes from seven learners and anonymous visitors', '{"requests":[{"at":0,"user":null,"path":"/api/dashboard"},{"at":4,"user":"u_an","path":"/api/dashboard"},{"at":4,"user":"u_an","path":"/api/dashboard?tab=streaks"},{"at":5,"user":null,"path":"/api/courses?category=react"},{"at":5,"user":null,"path":"/api/courses?category=react"},{"at":5,"user":"u_lan","path":"/api/dashboard"},{"at":9,"user":"u_lan","path":"/api/dashboard"},{"at":9,"user":"u_5124","path":"/api/courses"},{"at":13,"user":null,"path":"/api/courses?category=node"},{"at":13,"user":null,"path":"/api/dashboard?tab=streaks"},{"at":17,"user":"u_7781","path":"/api/dashboard?tab=streaks"},{"at":20,"user":null,"path":"/api/leaderboard"},{"at":24,"user":"u_5124","path":"/api/dashboard"},{"at":24,"user":null,"path":"/api/dashboard?tab=streaks"},{"at":28,"user":"u_5120","path":"/api/dashboard"},{"at":28,"user":"u_minh","path":"/api/dashboard"},{"at":28,"user":"u_an","path":"/api/courses?category=sql"},{"at":31,"user":null,"path":"/api/dashboard"},{"at":33,"user":"u_minh","path":"/api/dashboard"},{"at":37,"user":null,"path":"/api/dashboard"},{"at":40,"user":"u_an","path":"/api/dashboard"},{"at":43,"user":"u_7781","path":"/api/leaderboard"},{"at":43,"user":"u_thu","path":"/api/leaderboard"},{"at":46,"user":null,"path":"/api/courses?category=react"},{"at":47,"user":"u_5124","path":"/api/courses"},{"at":50,"user":"u_7781","path":"/api/courses"},{"at":52,"user":"u_7781","path":"/api/dashboard"},{"at":52,"user":null,"path":"/api/leaderboard"},{"at":52,"user":"u_lan","path":"/api/leaderboard"},{"at":54,"user":"u_an","path":"/api/courses?category=sql"},{"at":57,"user":"u_7781","path":"/api/dashboard?tab=streaks"},{"at":57,"user":"u_an","path":"/api/dashboard"},{"at":60,"user":"u_5124","path":"/api/courses"},{"at":61,"user":"u_thu","path":"/api/dashboard"},{"at":62,"user":"u_thu","path":"/api/courses