-- challenge chal_quiz_nrc_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nrc_231', (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nrc-2-3' AND is_deleted = false LIMIT 1), 'ttl-swr-evidence', 'TTL & stale-while-revalidate: read the headers and the log', 'Two statements on the leaderboard cache: what a CDN does with a stale response inside its stale-while-revalidate window, and what a stale-while-revalidate patch without single flight does to the database.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_231');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_231'), 'Response of GET https://app.codedev.test/api/leaderboard, stored by the CDN at 10:00:00:
cache-control: public, max-age=0, s-maxage=60, stale-while-revalidate=300

The origin is healthy and the CDN supports stale-while-revalidate. A learner requests the same URL at 10:03:00.

Statement: "The CDN answers at once with the stored response, now 180 seconds old, and fetches a fresh copy from the origin in the background."', 'single_choice'::question_type, 'True. For a shared cache the freshness lifetime is s-maxage=60, so at 180 seconds the response is stale, but it is still inside the stale-while-revalidate window (60 + 300 = 360 seconds). Inside that window the cache may answer with the stale response immediately and revalidate it in the background; the next request after the refresh gets the new copy. At 10:06:00 or later the response would be beyond the window and the request would wait for the origin. max-age=0 only concerns the browser. The misconception is that a response past its max-age always means waiting for the origin; that is the plain-TTL cliff the extension exists to avoid.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_231'), 'lib/cache.ts (second patch):
if (entry && age >= maxAge && age < maxAge + staleWhileRevalidate) {
  refresh(key);          // starts db.weeklyLeaderboard() in the background
  return entry.value;
}

Server log at the 09:00 peak:
09:01:00.004  cache STALE leaderboard:weekly age=60.00s -> background refresh started
09:01:00.051  cache STALE leaderboard:weekly age=60.05s -> background refresh started
...
09:01:01.962  cache STALE leaderboard:weekly age=61.96s -> background refresh started   (40 in total)

Statement: "Because all 40 requests were answered at once with the stale value, the database received a single leaderboard query at 09:01."', 'single_choice'::question_type, 'False. Answering at once is about latency; the log shows the load: each of the 40 stale requests started its own background refresh, because the code never checks whether a refresh for the key is already running. The database still runs 40 copies of the 2-second query, just without anyone waiting for them. The fix is single flight: remember the running fetch per key, let stale requests skip starting another, and let waiting requests join it. The misconception is that stale-while-revalidate by itself protects the origin; it removes waiting, not load.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_nrc_232 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nrc_232', (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nrc-2-3' AND is_deleted = false LIMIT 1), 'ttl-stale-while-revalidate', 'TTL and stale-while-revalidate', 'The CodeDev weekly leaderboard query takes about 2 seconds. With a plain 60-second TTL, the first request after each expiry waits for it, and at the 09:00 peak forty requests arrive in that window and start forty identical queries. Write SwrCache, a cache with maxAge and staleWhileRevalidate on a fake clock (seconds), that serves stale values while it revalidates, starts at most one fetch per key, and keeps serving the stale value when a revalidation fails.

new SwrCache(maxAge, staleWhileRevalidate, clock, origin): throw Error("invalid cache config") if either number is negative or not finite. get(key) returns a Promise<Served> with { status, value, error, fetchesStarted }. The age of a stored value is clock.now() minus the time its fetch completed. (1) age < maxAge: HIT, the stored value, no fetch. (2) maxAge <= age < maxAge + staleWhileRevalidate: STALE, the stored value at once, and start a background revalidation unless a fetch for this key is already running (fetchesStarted 1 if this request started it, else 0). (3) No stored value, or age >= maxAge + staleWhileRevalidate: MISS, wait for a fetch: join the fetch already running for the key (fetchesStarted 0), or start one (1). There is never more than one fetch per key at a time.

A successful fetch stores its value, dated at its completion time, and every MISS waiting on it gets that value. A failed fetch stores nothing and keeps the old value (stale-if-error until the stale window ends): later STALE requests keep getting the old value and the next one starts a new revalidation. A MISS waiting on a failed fetch gets { status: "MISS", value: null, error: <the error message> }. A failed background revalidation must not reject anything that nobody awaits. Keys are independent.

The runner: the n-th fetch of a key gets the n-th scripted answer of that key ({ value, takes } or { error, takes }) takes seconds after it starts; fetches that complete at time t are processed before requests that arrive at time t. Input: { "maxAge": s, "staleWhileRevalidate": s, "origin": { "<key>": [answers] }, "requests": [{ "at": s, "key": "<key>" }, ...] }. Output, per request: t=<at> <key>: <status> "<value>" or error "<message>", fetches=<n> answered t=<time>; then the number of fetches per key, or "error: <message>" if the constructor throws.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
