INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_232'), 1, 'A request can find a key in four situations: nothing stored, fresh, stale, expired; and independently, a fetch for that key may already be running. Which of these combinations start a new fetch, and which ones must wait for one?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_232'), 2, 'Look at what you need to remember per key besides the value: the time its fetch completed (not started), and the promise of the fetch that is running right now, if any. Remove that promise when the fetch settles, on success and on failure, and decide what happens to the stored value in each case.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_232'), 3, 'A similar timeline with maxAge 10 and a stale window of 20, where a fetch takes 3 s: t=0 MISS starts a fetch and is answered at t=3; t=12 is a HIT (age 9); t=14 is STALE and starts a refresh that completes at t=17; t=15 is STALE with no new fetch; t=18 is a HIT on the new value (age 1). Had the refresh failed at t=17, t=18 would still be STALE on the old value and would start the next refresh.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_232'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
