The action for the description field of a published course:

export async function saveDescription(id: string, description: string) {
  await db.course.update({ where: { id }, data: { description } });
  updateTag(`course:${id}`);
}

Statement: "After this action, every cached entry that contains the old description has been expired, although courses:list and the category tags were not touched."', 'single_choice'::question_type, 'True. The description is stored in exactly one cached read, getCourse, tagged course:<id>. The card reads select title, price, slug and category, so no card entry contains the old description. Expiring the list and category tags as well would rebuild the catalog and the category page with identical content: cost without benefit. The misconception is that an edit to a course must refresh every page that mentions the course; the question to ask is which cached data contains the changed field.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_311') AND order_index = 1)
    RETURNING id
)
