SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_311'), 'Cached reads on CodeDev:
  getCourse(id)         cacheTag(`course:${id}`)             every field of the course, with lessons
  getCatalogCards()     cacheTag("courses:list")             title, price, slug, category of published courses
  getCategoryCards(c)   cacheTag(`courses:category:${c}`)    the same card fields, for category c

export async function changeCategory(id: string, category: string) {
  await db.course.update({ where: { id }, data: { category } });
  updateTag(`course:${id}`);
  updateTag("courses:list");
  updateTag(`courses:category:${category}`);
}

An instructor moves published course 88 from react to testing. Server log right after:
10:02:15  GET /courses?category=testing   [cache miss] getCategoryCards testing
10:02:17  GET /courses                    [cache miss] getCatalogCards
10:02:19  GET /courses?category=react     (no miss)

Statement: "The react category page will drop course 88 on its next request, because expiring courses:list also expires the category lists."', 'single_choice'::question_type, 'False. Tags are compared as whole strings: the react entry was stored with courses:category:react only, and no call expired that tag. The log confirms it: the react page was served from the cache at 10:02:19 and still lists the course, and it will keep doing so until its time-based lifetime ends. The fix is to read the course before the update and also expire courses:category:<old category>. The misconception is that tags form a hierarchy, so that a "list" tag covers the category lists whose names look related.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_311') AND order_index = 2)
    RETURNING id
)
