-- challenge chal_coding_nrc_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nrc_312', (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nrc-3-1' AND is_deleted = false LIMIT 1), 'revalidation-targets', 'Revalidate exactly what an edit made wrong', 'After an instructor moved a course to another category, the old category page kept listing it; the hotfix revalidated the whole site after every save. Write revalidationTargets(catalog, event): the tags for revalidateTag and the paths for revalidatePath that one domain event makes necessary, no more and no less. Conventions: course:<id> holds every field of one course and is read by its page /course/<slug>; courses:list (the catalog /courses) and courses:category:<category> (one category page) hold the cards of published courses only, which show title, price, slug, category and the instructor''s name; instructor:<id> holds the instructor''s name for course pages; the category sidebar of /courses has no tag, so only the path /courses refreshes it. The catalog is the state before the event; each course has id, slug, title, description, price, category, instructorId and published. Rules. course_updated { courseId, changes } (changes may hold title, description, price, category, slug; any other key is ignored) and price_changed { courseId, price } (the same as changes { price }): a field counts as changed only when its new value differs from the catalog value; no changed field -> nothing. Otherwise course:<id>; if the course is published and a card field (title, price, slug, category) changed, also courses:list and courses:category:<current category>; if the category changed (published), also courses:category:<new category> and the path /courses; if the slug changed (published), the paths /course/<old slug> and /course/<new slug>. lesson_added { courseId, lessonId } -> course:<id>. course_published / course_unpublished { courseId }: when the course is already in that state -> nothing; otherwise course:<id>, courses:list, courses:category:<category> and the paths /course/<slug> and /courses. instructor_renamed { instructorId, name } -> instructor:<instructorId>, plus courses:list and courses:category:<c> for every category c of a published course of that instructor. An unknown courseId or event type -> nothing. Return { tags, paths }, each without duplicates and sorted with the default string sort. The runner checks every event on its own against the same catalog and prints a JSON array with one { tags, paths } per event.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
