INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_312'), 1, 'For each event, ask two questions: which fields really changed (compared with the catalog, not just sent by the form), and which cached reads show those fields? A tag belongs in the answer only if the answer to the second question includes it.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_312'), 2, 'Look at what the old state gives you: the current category and slug come from the catalog, the new ones from the event, and an edit that moves a course between categories or URLs makes both the old and the new one wrong. Collect everything into two Sets and sort at the end, so duplicates and order take care of themselves.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nrc_312'), 3, 'A similar mapping for a different feature: lessons are cached under lesson:<id> (title, body) and module:<moduleId> (lesson titles only). Renaming a lesson changes a field the module list shows, so it gives ["lesson:5", "module:2"]; editing only the body gives ["lesson:5"]; moving lesson 5 from module 2 to module 3 gives ["lesson:5", "module:2", "module:3"]; saving the same title again gives [].');
