}

// app/instructor/courses/[id]/actions.ts
export async function saveCourseDetails(id: string, data: DetailsForm) {
  await db.course.update({ where: { id }, data });
  updateTag(`course-${id}`);
}

$ npm run build
  Compiled successfully (no errors, no warnings)

Statement: "If updateTag were given a tag that no cached entry carries, the build or the server log would report it, so the clean build shows the two tags match."', 'single_choice'::question_type, 'False. A tag is an arbitrary string. Nothing compares the strings passed to cacheTag with the strings passed to updateTag or revalidateTag, and expiring a tag that no entry carries is not an error: it simply expires nothing. Here course:42 and course-42 are different strings, so every save leaves the cached course data in place until cacheLife ends it, up to an hour later. The misconception is that tags are checked like identifiers; to catch a mismatch you need one helper that builds the tag for readers and writers, and a test that saves and then reads.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_321') AND order_index = 1)
    RETURNING id
)
