-- challenge chal_coding_nrc_322 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nrc_322', (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nrc-3-2' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-course-page-never-updates', 'Spot the AI Mistake: the course page that never updates', 'The request sent to an AI coding assistant was: "Cache the course page so it is fast." The assistant cached the course data with getCourse = cached(..., { tags: course:<id>, revalidate: 3600 }) and kept the two server actions of the instructor dashboard, saveCourseDetails and changeCoursePrice. The page is fast and the public tests pass. Since the merge, instructors report that the course page keeps the old title and the old price after they save, for up to an hour, and learners saw 249000 VND on the course page but 199000 VND at checkout. Fix the assistant''s code so that after a successful save of a title or a price, the very next read of that course page shows the new value (a MISS that waits for fresh data, not a stale page), while caching keeps working: repeated reads are HITs, other courses stay cached when one course changes, and a rejected action (unknown course, empty title, invalid price) changes nothing and refreshes nothing. The starter contains a model of the Next.js data cache on a fake clock: updateTag(tag) expires entries at once, revalidateTag(tag, "max") marks them stale (the next read still returns the old value), and tags are compared as whole strings. The runner reads { courses, steps } where a step is { read }, { edit, title }, { price, amount } or { advance } (seconds), prints one line per step (a read prints the page and MISS, HIT or STALE) and finally the number of database reads. Do not change the database, the mini cache or the runner.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
