    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_331'), '// lib/course-public.ts
export async function getPublicCourse(id: string) {
  "use cache";
  cacheTag(`course:${id}`);
  cacheLife("minutes");
  return db.course.findUnique({ where: { id }, select: { id: true, title: true, price: true, lessons: true } });
}

// app/course/[id]/page.tsx
export default async function CoursePage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const course = await getPublicCourse(id);
  return (
    <>
      <CourseHeader course={course} />
      <Suspense fallback={<PanelSkeleton />}>
        <LearnerPanel courseId={id} listPrice={course.price} />  {/* reads cookies(), loads enrollment and coupon */}
      </Suspense>
    </>
  );
}

Statement: "When Lan and Binh open course 42 within the same minute, they can share one cached copy of the course data while each of them gets their own enrollment, progress and coupon price."', 'single_choice'::question_type, 'True. getPublicCourse takes only the course id and reads nothing about the user, so its cached result is the same for everyone and safe to share; it is cached per id with the course tag. LearnerPanel reads the session cookie, which makes it dynamic: it runs for every request and its output is never stored in the shared cache, and it computes the coupon price from the public list price inside one request. The misconception is that a page is either cached for everyone or for nobody; splitting by component lets the expensive public part be shared while the personal part stays per request.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nrc_331') AND order_index = 1)
    RETURNING id
)
