VALUES ('chal_coding_nrc_332', (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nextjs-rendering-caching') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nrc-3-3' AND is_deleted = false LIMIT 1), 'split-public-and-personal-data', 'Compose the course page from shared and personal data', 'The course page response used to mix course data with the learner''s progress and coupon price and was cached for everyone; learners saw each other''s progress. Write renderCoursePage(req, ttl, deps), which returns the page text for one request { at (seconds), userId (null for an anonymous visitor), courseId }. Public data: deps.sharedCache is one cache shared by every request of every user (values are stored as JSON). Keep the public course { id, title, price, lessons } there under the key course:<courseId> together with the time you stored it; it is fresh while at < storedAt + ttl. When it is missing or no longer fresh, call deps.loadPublicCourse(courseId) once and store the result. If the loader returns null, return "404 Not Found", store nothing and load nothing else. Personal data is never written to the shared cache and is loaded on every request that needs it: for a signed-in learner call deps.loadEnrollment(userId, courseId) first; only if they are not enrolled call deps.loadCoupon(userId). Anonymous visitors cause no personal loads. A coupon { code, percent, courses, expiresAt } applies when percent is an integer from 1 to 100, at < expiresAt, and courses is "all" or contains the course id; the price after it is Math.round(price * (100 - percent) / 100). Page text, with H = "<title> | <lessons> lessons": anonymous, or signed in without an applicable coupon -> "H | <price> VND | Enroll"; enrolled -> "H | Enrolled, <progress>% complete"; with an applicable coupon -> "H | <new price> VND with coupon <code> (list <price> VND) | Enroll". Requests arrive in time order. The runner prints each page with the loads it caused (public:<id>, enrollment:<user>:<id>, coupon:<user>), then the keys of the shared cache and the number of public loads.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
